 run([str(a/'tests/eka_cpu_tests')],'literal-pc-native-tests.log')
elif stage=='unit':run(['node',str(a/'tests/test_aot_wasm.js'),'--exit-census'],'literal-pc-unit-instrumented.log')
elif stage=='faults':
 for name,mode in [('conditional',0),('candidate',128)]:
  run(['python3','src/tests/benchmark/run_cpu_fault_matrix.py',str(a),str(s/f'literal-pc-fault-{name}'),'--ir-policy','7','--code-compare','2','--tlb-hash','1','--execution-limits','512,16,8,512','--predicated-leaves','1','--exit-census','0','--leaf-features',str(mode),'--literal-pc-veneers'],f'literal-pc-fault-{name}.log')
elif stage=='replay':
 for name,mode,verify in [('control',0,1024),('candidate',128,1024),('normal',128,0)]:
  run(['node','benchmark.ts',str(s/'assets'),str(s/f'literal-pc-replay-{name}'),'1600'],f'literal-pc-replay-{name}.log',r/'src/tests/wasm',dict(e,EKA2L1_LEAF_FEATURES=str(mode),EKA2L1_AOT_VERIFY=str(verify)))
  run(['python3','src/tests/benchmark/compare.py',str(s/'merge-20260930-native/run-0/frames'),str(s/f'literal-pc-replay-{name}')],f'literal-pc-compare-{name}.json')
  v=json.loads((s/f'literal-pc-compare-{name}.json').read_text());assert v['match'] and v['frames']==1600 and v['audio']['sample_frames']==4656051
