 run(['node','benchmark.ts',str(s/'assets'),str(s/'literal-pc-long-replay'),'360',str(r/'src/tests/benchmark/snakes-length-long.input'),'42000000'],'literal-pc-long-replay.log',r/'src/tests/wasm',dict(e,EKA2L1_LEAF_FEATURES='128'))
