from pathlib import Path
import json,statistics,subprocess,sys,hashlib
r=Path('/home/claude/code/EKA2L1');s=Path('/home/claude/.scratch/eka-benchmark');d=r/'src/tests/benchmark';p=d/'LITERAL_PC_EVIDENCE.json';e=json.loads(p.read_text());e['timing']={}
text='\n## Serial gameplay timing\n\nAll modes retain policy 7, conditional integer leaves and limits 512/16/8/512. The matching control uses feature 0 and the candidate feature 128 in the same frozen binary. The untouched delivered conditional-only archive is a separate baseline. Diagnostics and interpreter checking are off; guest work and scheduling are identical within each route.\n\n| Route/batch | Matching control | Literal PC veneers | Untouched live archive |\n| --- | ---: | ---: | ---: |\n'
results=[]
for scene in ['long','standard']:
 for batch in ['a','b']:
  path=s/f'literal-pc-timing-{scene}-{batch}';rows=json.loads((path/'measurements.json').read_text());host=json.loads((s/f'literal-pc-timing-{scene}-{batch}-host.json').read_text())
  assert len(rows)==6 and host['returncode']==0 and not host['foreign_jobs']
  expected=(6445351805,9476989025,380)if scene=='long'else(8980877653,11957513019,381)
  assert {tuple(x['measurement'][k]for k in ['first_instructions','last_instructions','presentations'])for x in rows}=={expected}
  reports={x['name']:json.loads((path/x['name']/'report.json').read_text())for x in rows}
  for name,z in reports.items():
   assert z['ir_mode']==7 and not z['exit_census'] and z['verify_aot']==0 and z['guest_profile_stride']==0 and not z['measurement']['detailed']
   assert z['leaf_features']==(128 if name.startswith('candidate')else 0)
   assert z['predicated_leaves']==1 and z['execution_limits']==[512,16,8,512]
   assert z['tlb_hash']==1 and z['code_compare']==2 and z['code_lookup']==0 and z['eager_regions']==0 and z['shared_audio']
   assert z['wasm_sha256']==(json.loads((s/'predicated-leaf-candidate/source.json').read_text())['files']['eka2l1.wasm']if name.startswith('baseline')else e['archive']['files']['eka2l1.wasm'])
  modes=['control','candidate','baseline'];means={n:statistics.mean(x['measurement']['wall_seconds']for x in rows if x['name'].startswith(n+'-'))for n in modes}
  pairs={n:[next(x['measurement']['wall_seconds']for x in rows if x['name']==f'{n}-{rep}')/next(x['measurement']['wall_seconds']for x in rows if x['name']==f'candidate-{rep}')-1 for rep in [1,2]]for n in ['control','baseline']}
  e['timing'][scene+'-'+batch]=dict(actual_order=[x['name']for x in rows],rows=rows,reports=reports,host_observer=host,means=means,paired_throughput_changes=pairs)
  text+='| '+scene+' '+batch+' | '+' | '.join(f'{means[n]:.4f}s'for n in modes)+' |\n';results.append((scene,batch,means,pairs))
text+='\nEach cell averages two observations. All 24 samples remain, including slow runs. A uses control/candidate/live and its mirror; B uses candidate/live/control and its mirror, moving every mode between positions. Actual per-run orders are retained. Comparisons pair corresponding halves and are not all immediately adjacent. The two-second host observer watches competing test/profile jobs and records passive frequency/thermal context; it cannot exclude all host activity or assign a cause to slow samples. Startup includes guest work and is not an isolated compilation measure.\n\n'
for scene,batch,m,pairs in results:
 text+=f'- {scene} {batch} order '+', '.join(e['timing'][scene+'-'+batch]['actual_order'])+': '+ '; '.join(f"versus {n}: {100*(m[n]/m['candidate']-1):+.2f}% throughput, paired {100*pairs[n][0]:+.2f}% / {100*pairs[n][1]:+.2f}%"for n in ['control','baseline'])+'.\n'
text+='\nNo automatic default or delivery change follows. Separately checked diagnostics measure dispatch, dependency and guard costs; normal live/audio acceptance is required for any promotion.\n'
e['timing_harness']={name:dict(sha256=hashlib.sha256((s/name).read_bytes()).hexdigest(),source=(s/name).read_text()) for name in ['run_literal_pc_timing.py','guarded_literal_pc_timings.py','record_literal_pc_timings.py']}
e['status']='correctness and all 24 timing observations retained; interpretation and diagnostic census pending; no deployment'
p.write_text(json.dumps(e,indent=2)+'\n');p=d/'LITERAL_PC_RESULTS.md';p.write_text(p.read_text().split('\n## Serial gameplay timing')[0]+text);print(text)
